package com.johnwpb.torquewidgets;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;
public class GaugeSettings extends Activity {
 int id; SharedPreferences prefs; LinearLayout panel;
 EditText field(String key,String def){TextView label=new TextView(this);label.setText(key);panel.addView(label);EditText e=new EditText(this);e.setSingleLine(true);e.setText(prefs.getString(key,def));panel.addView(e);if(key.endsWith("color")){e.setFocusable(false);e.setOnClickListener(v->pickColor(key,e));}return e;}
 public void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);setResult(RESULT_CANCELED);if(id<0){LinearLayout l=new LinearLayout(this);l.setOrientation(1);TextView t=new TextView(this);t.setText("Torque Widgets — add independent gauges from your home screen widget picker.");l.addView(t);setContentView(l);return;}prefs=getSharedPreferences("gauge"+id,0);ScrollView scroll=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(24,24,24,24);scroll.addView(panel);setContentView(scroll);
 String[] keys={"Name","PID","Minimum","Maximum","Units","Multiplier","Offset","Font color","Tick color","Indicator color","Needle color"};String[] defaults={"Coolant","05","0","260","°F","1.8","32","#84D5FF","#84D5FF","#84D5FF","#84D5FF"};EditText[] fields=new EditText[keys.length];for(int i=0;i<keys.length;i++)fields[i]=field(keys[i],defaults[i]);Switch circle=new Switch(this);circle.setText("Circular gauge (off = semicircle)");circle.setChecked(prefs.getBoolean("circle",false));panel.addView(circle);Switch info=new Switch(this);info.setText("Display information only");info.setChecked(prefs.getBoolean("info",false));panel.addView(info);Spinner style=new Spinner(this);style.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Illuminated segments","Sweeping needle","Continuous arc","None"}));style.setSelection(prefs.getInt("style",0));panel.addView(style);Button save=new Button(this);save.setText("Save");panel.addView(save);save.setOnClickListener(v->{try{float min=Float.parseFloat(fields[2].getText().toString()),max=Float.parseFloat(fields[3].getText().toString());if(!Float.isFinite(min)||!Float.isFinite(max)||max<=min)throw new Exception();for(int i=5;i<7;i++)if(!Float.isFinite(Float.parseFloat(fields[i].getText().toString())))throw new Exception();for(int i=7;i<keys.length;i++)android.graphics.Color.parseColor(fields[i].getText().toString());if(fields[1].getText().toString().trim().isEmpty())throw new Exception();SharedPreferences.Editor ed=prefs.edit();for(int i=0;i<keys.length;i++)ed.putString(keys[i],fields[i].getText().toString().trim());ed.putBoolean("circle",circle.isChecked()).putBoolean("info",info.isChecked()).putInt("style",style.getSelectedItemPosition()).apply();Intent result=new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);setResult(RESULT_OK,result);sendBroadcast(new Intent(this,CoolantWidget.class).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE).putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS,new int[]{id}));finish();}catch(Exception ex){Toast.makeText(this,"Check range, conversion and hex colors",Toast.LENGTH_LONG).show();}});}

 void pickColor(String key, EditText target){
  final float[] hsv={200,.5f,1}; int original=android.graphics.Color.parseColor(target.getText().toString()); android.graphics.Color.colorToHSV(original,hsv);
  LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(20,12,20,12);
  SeekBar[] bars={new SeekBar(this),new SeekBar(this),new SeekBar(this)};
  TextView before=new TextView(this),after=new TextView(this);before.setText("Original");after.setText("Selected");before.setBackgroundColor(original);before.setTextColor(android.graphics.Color.WHITE);after.setTextColor(android.graphics.Color.WHITE);
  EditText hex=new EditText(this);hex.setSingleLine(true);hex.setHint("#RRGGBB");
  android.view.View spectrum=new android.view.View(this){
   android.graphics.Paint p=new android.graphics.Paint(3);
   protected void onDraw(android.graphics.Canvas c){float w=getWidth(),h=getHeight();if(w<=0||h<=0)return;
    p.setShader(new android.graphics.LinearGradient(0,0,w,0,new int[]{0xffff0000,0xffffff00,0xff00ff00,0xff00ffff,0xff0000ff,0xffff00ff,0xffff0000},null,android.graphics.Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);
    p.setShader(new android.graphics.LinearGradient(0,0,0,h,0x00ffffff,0xffffffff,android.graphics.Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(5);p.setColor(0xff000000);float x=hsv[0]/360*w,y=(1-hsv[1])*h;c.drawCircle(x,y,12,p);p.setStrokeWidth(2);p.setColor(-1);c.drawCircle(x,y,12,p);p.setStyle(android.graphics.Paint.Style.FILL);}
   public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0||e.getAction()==2||e.getAction()==1){getParent().requestDisallowInterceptTouchEvent(true);bars[0].setProgress(Math.min(359,Math.max(0,Math.round(e.getX()/getWidth()*359))));bars[1].setProgress(Math.min(100,Math.max(0,Math.round((1-e.getY()/getHeight())*100))));if(e.getAction()==1)performClick();return true;}return true;}
   public boolean performClick(){super.performClick();return true;}
  };
  box.addView(spectrum,new LinearLayout.LayoutParams(-1,(int)(180*getResources().getDisplayMetrics().density)));
  String[] names={"Hue","Saturation","Brightness"};for(int i=0;i<3;i++){TextView label=new TextView(this);label.setText(names[i]);box.addView(label);bars[i].setMax(i==0?359:100);bars[i].setProgress(Math.round(hsv[i]*(i==0?1:100)));box.addView(bars[i]);}
  box.addView(before);box.addView(after);box.addView(hex);
  final boolean[] busy={false};Runnable refresh=()->{if(busy[0])return;busy[0]=true;hsv[0]=bars[0].getProgress();hsv[1]=bars[1].getProgress()/100f;hsv[2]=bars[2].getProgress()/100f;int color=android.graphics.Color.HSVToColor(hsv);after.setBackgroundColor(color);after.setTextColor(hsv[2]>.65f&&hsv[1]<.65f?0xff000000:0xffffffff);hex.setText(String.format(java.util.Locale.US,"#%06X",color&0xffffff));spectrum.invalidate();busy[0]=false;};
  for(SeekBar bar:bars)bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){refresh.run();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
  hex.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){if(busy[0]||!s.toString().matches("#[0-9a-fA-F]{6}"))return;busy[0]=true;int color=android.graphics.Color.parseColor(s.toString());android.graphics.Color.colorToHSV(color,hsv);bars[0].setProgress(Math.round(hsv[0]));bars[1].setProgress(Math.round(hsv[1]*100));bars[2].setProgress(Math.round(hsv[2]*100));after.setBackgroundColor(color);spectrum.invalidate();busy[0]=false;}public void afterTextChanged(android.text.Editable e){}});
  refresh.run();ScrollView scroll=new ScrollView(this);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(key).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("OK",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{String value=hex.getText().toString();if(!value.matches("#[0-9a-fA-F]{6}")){hex.setError("Enter #RRGGBB");return;}target.setText(value.toUpperCase(java.util.Locale.US));dialog.dismiss();});
 }
}
